/**
 * @name Path traversal in static file handling
 * @description User-controlled path used to build filesystem path
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(Call c |
      c.getFunc().(Attribute).getName() = "get"
      and source.asExpr() = c
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(Call c |
      c.getFunc().(Attribute).getName() = ["joinpath", "resolve", "open", "stat"]
      and sink.asExpr() = c.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Filesystem path built from $@.", source.getNode(), "user-controlled data"

/**
 * @name Request-derived data into HTTP header values
 * @description Header value built from request data may allow response splitting / header injection
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode c |
      c.asExpr().(Call).getFunc().(Attribute).getAttr() = ["get", "getall", "match_info"]
      and source = c
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode c |
      c.asExpr().(Call).getFunc().(Attribute).getAttr() = "update"
      and sink = c.getArg(0)
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Header value from $@.", source.getNode(), "request data"

/**
 * @name Path traversal in static file resolution
 * @description Request-derived path components flowing into filesystem path construction
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-static-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module C implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node src) {
    exists(Attribute a | a.getAttr() = ["match_info", "rel_url", "raw_path"] and src.asExpr() = a)
    or exists(Subscript s |
      s.getObject().(Attribute).getAttr() = ["match_info", "rel_url"]
      and src.asExpr() = s
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode c |
      c.asExpr().(Call).getFunc().(Attribute).getAttr() =
        ["joinpath", "join", "normpath", "abspath", "resolve", "open", "stat", "is_file", "exists"]
      and sink = c.getArg(0)
    )
  }
}

module F = TaintTracking::Global<C>;
import F::PathGraph

from F::PathNode s, F::PathNode k
where F::flowPath(s, k)
select k.getNode(), s, k, "Filesystem path derived from $@.", s.getNode(), "request path data"

/**
 * @name HTTP header injection from request data
 * @description Request-derived values written into response headers
 * @kind problem
 * @problem.severity error
 * @id py/aiohttp-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module HIConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode c | source = c |
      exists(Attribute a | a = c.asExpr().(Call).getFunc() |
        a.getAttr() = ["get", "getall"] and
        a.getObject().(Attribute).getAttr() = ["headers", "match_info", "query"]
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(Subscript s |
      sink.asExpr() = s and
      s.getObject().(Attribute).getAttr() = "headers"
    )
  }
}

module HIFlow = TaintTracking::Global<HIConfig>;

from DataFlow::Node source, DataFlow::Node sink
where HIFlow::flow(source, sink)
select sink, "Response header value derived from $@.", source, "request data"
